shader:
@group(0) @binding(0) var<storage, read_write> lane0: array<f32>;
@group(0) @binding(1) var<storage, read_write> head: array<f32>;

@compute @workgroup_size(64, 1, 1)
fn p0(@builtin(global_invocation_id) gid: vec3<u32>, @builtin(num_workgroups) grid: vec3<u32>) {
  let i: u32 = gid.x + gid.y * grid.x * 64u;
  if (i >= 1024u) { return; }
  let v_0: f32 = lane0[0u + i];
  let v_2: f32 = (v_0 * v_0);
  let v_1: f32 = lane0[1024u + i];
  let v_5: f32 = (v_1 * v_1);
  let v_8: f32 = (v_2 + v_5);
  let v_11: f32 = sqrt(v_8);
  lane0[2048u + i] = v_11;
}
